import { Injectable } from '@nestjs/common';
import { TransactionHost } from '@nestjs-cls/transactional';
import { eq, type SQL } from 'drizzle-orm';
import type {
  Database,
  Transaction,
} from '../../../src/core/database/drizzle.js';
import {
  database,
  type DrizzleTransactions,
  inTransaction,
} from '../../../src/core/database/transactions.js';
import type { PageQuery } from '../../../src/core/http/pagination.js';
import { AuditService } from '../../../src/iam/audit/audit.service.js';
import type { Principal } from '../../../src/iam/auth/principal.js';
import {
  recordValues,
  recordView,
} from '../../../src/platform/records/record.js';
import { RecordLifecycle } from '../../../src/platform/records/record-contract.js';
import { RecordStore } from '../../../src/platform/records/record-store.js';
import { TEST_ITEM } from './test-item.record.js';
import { TEST_ITEM_RESOURCE } from './test-item.resource.js';
import type {
  CreateTestItemDto,
  TestItem,
  UpdateTestItemDto,
} from './test-item.schemas.js';
import { testItems } from './test-items.tables.js';

/**
 * Test items: the writes and the reads. Each write, its audit entry and what its
 * capabilities do (RecordLifecycle: watchers, revisions) commit in one transaction;
 * what test-item.record.ts decides (the recycle bin, teams) RecordStore does.
 * Generated by `pnpm feature:add` (tools/feature): the business logic goes where the comments say "Business logic".
 */
@Injectable()
export class TestItemsService {
  constructor(
    private readonly txHost: TransactionHost<DrizzleTransactions>,
    private readonly audit: AuditService,
    private readonly lifecycle: RecordLifecycle,
    private readonly records: RecordStore,
  ) {}

  /** The current transaction, or the database outside one (core/database/transactions.ts). */
  private get db() {
    return database(this.txHost);
  }

  /** A new one of `owner`'s; `by` is who acts, when not the owner (a system job). */
  async create(
    owner: Principal,
    dto: CreateTestItemDto,
    { by = owner }: { by?: Principal } = {},
  ): Promise<TestItem> {
    // Business logic: check or derive values here, before the transaction.
    return inTransaction(this.txHost, async (tx) => {
      const [row] = await tx
        .insert(testItems)
        .values({
          // Its owner, and with teams the owner's team.
          ...(await this.records.owner(owner, tx)),
          ...recordValues(TEST_ITEM, dto),
        } as typeof testItems.$inferInsert)
        .returning();
      await this.lifecycle.created(tx, { row: row!, owner, by });
      // Business logic: what else happens with it, in this transaction (events, notifications).
      await this.audit.recordChange(
        by,
        TEST_ITEM_RESOURCE,
        { action: 'created', id: row!.id, after: recordView(TEST_ITEM, row!) },
        tx,
      );
      return row!;
    });
  }

  /** One, or a 404 (with `deleted`, one in the recycle bin). */
  findOne(
    id: string,
    db: Database | Transaction = this.db,
    options: { deleted?: boolean } = {},
  ) {
    return this.records.findOne<TestItem>(id, db, options);
  }

  /**
   * A page of those matching `where` (the caller's read filter, from AccessService), newest
   * first; `extra`: sort values that aren't columns (the list's sortSelect(query)).
   */
  findPage(
    where: SQL | undefined,
    query: PageQuery,
    extra: Record<string, SQL.Aliased> = {},
  ) {
    return this.records.findPage<TestItem>(where, query, extra);
  }

  /** Runs a read of your own on its table (exports, bulk actions, search). */
  query<T>(read: (db: Database) => Promise<T>) {
    return read(this.db);
  }

  /** Changes one; the audit entry holds what changed, from → to. */
  async update(
    by: Principal,
    row: TestItem,
    dto: UpdateTestItemDto,
    ip?: string,
    { restoredFrom }: { restoredFrom?: number } = {},
  ) {
    const changes = recordValues(TEST_ITEM, dto);
    if (Object.keys(changes).length === 0) {
      return row; // nothing to change
    }
    // Business logic: what a change must respect, here.
    return inTransaction(this.txHost, async (tx) => {
      const [updated] = await tx
        .update(testItems)
        .set(changes)
        .where(eq(testItems.id, row.id))
        .returning();
      await this.lifecycle.updated(tx, {
        before: row,
        after: updated!,
        by,
        restoredFrom,
      });
      await this.audit.recordChange(
        by,
        TEST_ITEM_RESOURCE,
        {
          action: 'updated',
          id: row.id,
          before: recordView(TEST_ITEM, row),
          after: recordView(TEST_ITEM, updated!),
        },
        tx,
        ip,
      );
      return updated!;
    });
  }

  /** Deletes one: to the recycle bin (restorable until purged) when it has one, else for good. */
  async delete(by: Principal, row: TestItem, ip?: string) {
    // Business logic: what a delete must respect, here.
    await inTransaction(this.txHost, async (tx) => {
      await this.records.delete(tx, by, row);
      await this.audit.recordChange(
        by,
        TEST_ITEM_RESOURCE,
        { action: 'deleted', id: row.id, before: recordView(TEST_ITEM, row) },
        tx,
        ip,
      );
    });
  }

  /** Out of the recycle bin (POST /v1/test-items/{id}/restore, a bulk restore). */
  async restore(by: Principal, row: TestItem, ip?: string) {
    return inTransaction(this.txHost, async (tx) => {
      const restored = await this.records.restore<TestItem>(tx, row);
      await this.audit.recordChange(
        by,
        TEST_ITEM_RESOURCE,
        {
          action: 'restored',
          id: row.id,
          after: recordView(TEST_ITEM, restored),
        },
        tx,
        ip,
      );
      return restored;
    });
  }
}
